'use strict';
/* RAPID V5 FINAL WALK-FORWARD
   Fixed finalists only; no optimization here.
   BASE = current live.
   A = #1297: block 02,06,12,18 + H1 sep >= .10 (simple robust finalist)
   B = #1369: block 02,06,12,18 + H1 sep >= .15
   C = #1405: block 02,06,12,18 + H1 sep >= .18
   D = #685 : block 02,12 + H1 sep >= .18 (simpler fewer hour blocks)
   Core body=.65, EMA<=1.5 ATR, range<=2, RR/SL/maxBars unchanged.
*/
const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function ema(v,p){let o=Array(v.length).fill(NaN),e=v[0],k=2/(p+1);for(let i=0;i<v.length;i++){if(i)e=v[i]*k+e*(1-k);if(i>=p-1)o[i]=e}return o}function atr(c,p=14){let o=Array(c.length).fill(NaN),s=0;for(let i=1;i<c.length;i++){let tr=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));s+=tr;if(i>p){let j=i-p,old=Math.max(c[j].h-c[j].l,Math.abs(c[j].h-c[j-1].c),Math.abs(c[j].l-c[j-1].c));s-=old}if(i>=p)o[i]=s/p}return o}function h1(){let a=[],z;for(const x of M){let d=new Date(x.t),t=Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),d.getUTCHours());if(!z||z.t!==t){z={t,o:x.o,h:x.h,l:x.l,c:x.c};a.push(z)}else{z.h=Math.max(z.h,x.h);z.l=Math.min(z.l,x.l);z.c=x.c}}return a}const H=h1(),ME=ema(M.map(x=>x.c),20),MA=atr(M),HC=H.map(x=>x.c),H20=ema(HC,20),H50=ema(HC,50),HA=atr(H);let hp=0,HI=[];for(let i=0;i<M.length;i++){while(hp+1<H.length&&H[hp+1].t<=M[i].t)hp++;HI[i]=Math.max(0,hp-1)}
function run(q){let out=[],p=null;for(let i=60;i<M.length-1;i++){if(p){let b=M[i],sl=p.s==='BUY'?b.l<=p.sl:b.h>=p.sl,tp=p.s==='BUY'?b.h>=p.tp:b.l<=p.tp;if(sl||tp||i-p.ei+1>=10){let px=sl?p.sl:tp?p.tp:b.c,r=(p.s==='BUY'?px-p.en:p.en-px)/p.risk;out.push({t:M[p.si].t,r,s:p.s,h:new Date(M[p.si].t).getUTCHours()});p=null}if(p)continue}let h=HI[i],hr=new Date(M[i].t).getUTCHours();if([20,22].includes(hr)||q.block.includes(hr)||h<52)continue;if(![ME[i],MA[i],H20[h],H50[h],HA[h],H20[h-2]].every(Number.isFinite)||!(MA[i]>0&&HA[h]>0))continue;let sep=Math.abs(H20[h]-H50[h])/HA[h];if(sep<q.sep)continue;let bull=HC[h]>H20[h]&&H20[h]>H50[h]&&H20[h]>H20[h-2],bear=HC[h]<H20[h]&&H20[h]<H50[h]&&H20[h]<H20[h-2];if(!bull&&!bear)continue;let hi=-Infinity,lo=Infinity;for(let j=i-3;j<i;j++){hi=Math.max(hi,M[j].h);lo=Math.min(lo,M[j].l)}let rg=M[i].h-M[i].l,body=Math.abs(M[i].c-M[i].o);if(!rg||body/MA[i]<.65||rg/MA[i]>2)continue;let cp=(M[i].c-M[i].l)/rg;if(Math.abs(M[i].c-ME[i])/MA[i]>1.5)continue;let buy=bull&&M[i].c>hi&&cp>=.72&&M[i].c>ME[i],sell=bear&&M[i].c<lo&&cp<=.28&&M[i].c<ME[i];if(!buy&&!sell)continue;let side=buy?'BUY':'SELL';if(side==='BUY'&&[3,16].includes(hr))continue;let en=M[i+1].o,sw=side==='BUY'?Math.min(M[i].l,M[i-1].l):Math.max(M[i].h,M[i-1].h),risk=Math.max(MA[i]*.65,Math.abs(en-sw));if(risk>MA[i]*1.35)continue;let rr=side==='BUY'?.85:.8;p={s:side,en,risk,sl:side==='BUY'?en-risk:en+risk,tp:side==='BUY'?en+risk*rr:en-risk*rr,ei:i+1,si:i}}return out}
function S(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else{if(x.r<0)gl+=-x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
const C=[['BASE',{block:[],sep:.08}],['A #1297',{block:[2,6,12,18],sep:.10}],['B #1369',{block:[2,6,12,18],sep:.15}],['C #1405',{block:[2,6,12,18],sep:.18}],['D #685',{block:[2,12],sep:.18}]],R=C.map(([n,q])=>[n,run(q)]);console.log('RAPID V5 — FINAL WALK-FORWARD');console.log('Core RR/SL/maxBars unchanged\nFULL PERIOD');for(const [n,a] of R)console.log(n.padEnd(9),F(S(a)));
let lo=M[0].t,hi=M.at(-1).t,sp=(hi-lo)/6,W={};R.forEach(([n])=>W[n]={pos:0,pf:0,better:0});console.log('\n6-BLOCK STABILITY');for(let k=0;k<6;k++){let a=lo+k*sp,b=k===5?hi+1:lo+(k+1)*sp,bs=S(R[0][1].filter(x=>x.t>=a&&x.t<b));console.log(`\nBLOCK ${k+1} ${new Date(a).toISOString().slice(0,10)} → ${new Date(b-1).toISOString().slice(0,10)}`);for(const [n,tr] of R){let s=S(tr.filter(x=>x.t>=a&&x.t<b));console.log(n.padEnd(9),F(s));if(s.net>0)W[n].pos++;if(s.pf>=1)W[n].pf++;if(n!=='BASE'&&s.pf>=bs.pf&&s.dd<=bs.dd)W[n].better++}}
console.log('\nSCORECARD');for(const [n] of R){let w=W[n];console.log(`${n.padEnd(9)} positive ${w.pos}/6 | PF>=1 ${w.pf}/6${n==='BASE'?'':` | PF>=BASE & DD<=BASE ${w.better}/6`}`)}
console.log('\nSIDE CHECK');for(const [n,tr] of R){console.log(n);console.log(' BUY ',F(S(tr.filter(x=>x.s==='BUY'))));console.log(' SELL',F(S(tr.filter(x=>x.s==='SELL'))))}
console.log('\nRECENT JUL→END');let recent=Date.UTC(2026,6,1);for(const [n,tr] of R)console.log(n.padEnd(9),F(S(tr.filter(x=>x.t>=recent))));console.log('\nRule: choose robustness, not highest full-period PF. Prefer fewer filters if stability is comparable.');